static void on_name_changed(void *ctx, const char *value) {
    struct editor_state *s = ctx;          /* the widget's own state */
    snprintf(s->name, sizeof s->name, "%s", value);
}

static void editor_run(void) {
    struct editor_state s = {0};           /* automatic storage: lives here */
    editor_bind(&s, on_name_changed);      /* pass the owner, not a global */
    editor_show(&s);
}                                          /* state dies with its owner */
